    categories: string[];
  };
}

export const searchBusinessesWithAI = async (query: string, businesses: Business[], language: string = 'ar'): Promise<AISearchResponse> => {
  try {
    const simplifiedData = businesses.map(b => ({
      id: b.id,
      name: b.name,
      description: b.description,
      category: b.category,
      services: b.services,
      isOccupied: b.isOccupied
    }));

    const categories = [...new Set(businesses.map(b => b.category).filter(c => c !== 'AVAILABLE'))];

    const prompt = `
      You are an intelligent search engine for the Business Developers District.
      Data: ${JSON.stringify(simplifiedData)}
      Available Categories: ${JSON.stringify(categories)}
      User Query: "${query}"
      Task: Analyze the user's query and return matching IDs with a score (0-100) and filters.
      Sort results by relevance (best matches first).
      Return JSON Object only: {"results": [{"id": "...", "score": 95}], "filters": {"status": "...", "categories": []}}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    const text = response.text || "{}";
    const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const result = JSON.parse(cleanText);

    return {
      results: result.results || [],
      filters: {
        status: result.filters?.status || 'all',
        categories: result.filters?.categories || []
      }
    };
  } catch (error) {
    console.error("AI Search Error:", error);
    return { results: [], filters: { status: 'all', categories: [] } };
  }
};

export const generateBusinessMatches = async (myProfile: BusinessGenome, availableBusinesses: Business[], language: string = 'ar'): Promise<MatchResult[]> => {
  try {
    // Optimization: Only send necessary data for matching to avoid payload limits and timeouts
    const simplifiedCandidates = availableBusinesses
        .filter(b => b.isOccupied && b.genomeProfile)
        .slice(0, 12) // Limit candidates to prevent "Rpc failed" due to long processing/large payloads
        .map(b => ({
           id: b.id,
           name: b.name,
           sector: b.genomeProfile?.industrySector,
           offers: b.genomeProfile?.servicesOffered,
           needs: b.genomeProfile?.servicesNeeded,
           size: b.genomeProfile?.companySize
        }));

    const prompt = `
      You are the "Business Genome Matching Engine" for a digital business district.

      YOUR PROFILE (The User):
      ${JSON.stringify({ sector: myProfile.industrySector, offers: myProfile.servicesOffered, needs: myProfile.servicesNeeded })}

      CANDIDATE ECOSYSTEM:
      ${JSON.stringify(simplifiedCandidates)}

      TASK:
      Analyze compatibility and return the TOP 6 matches. 
      Output Language: ${language === 'ar' ? 'Arabic' : language === 'es' ? 'Spanish' : 'English'}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              companyId: { type: Type.STRING },
              score: { type: Type.NUMBER },
              matchReason: { type: Type.STRING },
              sharedInterests: { type: Type.ARRAY, items: { type: Type.STRING } },
              collaborationOpportunity: { type: Type.STRING },
              analysisPoints: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    factor: { type: Type.STRING },
                    description: { type: Type.STRING }
                  }
                }
              }
            },
            required: ['companyId', 'score', 'matchReason', 'collaborationOpportunity']
          }
        }
      }
    });

    const text = response.text || "[]";
    return JSON.parse(text) as MatchResult[];

  } catch (error) {
    console.error("AI Matching Error:", error);
    return [];
  }
};

