export const generateBusinessAdvice = async (query: string, chatHistory: string[], language: string = 'ar'): Promise<string> => {
  try {
    const model = 'gemini-3-flash-preview';

    let prompt = '';
    if (language === 'ar') {
       prompt = `
      تاريخ المحادثة:
      ${chatHistory.join('\n')}

      سؤال المستخدم الحالي: ${query}

      قدم إجابة مفيدة وموجزة بصفتك مساعد أعمال ذكي في منصة مطورو الاعمال.
      `;
    } else if (language === 'es') {
       prompt = `
      Historial de chat:
      ${chatHistory.join('\n')}

      Pregunta actual del usuario: ${query}

      Proporcione una respuesta útil y concisa como asistente de negocios inteligente en la plataforma Business Developers.
      `;
    } else {
      prompt = `
      Chat History:
      ${chatHistory.join('\n')}

      Current User Question: ${query}

      Provide a helpful and concise answer as a smart business assistant on the Business Developers platform.
      `;
