}

export const searchBusinessesWithAI = async (query: string, businesses: Business[], language: string = 'ar'): Promise<AISearchResponse> => {
  try {
    const simplifiedData = businesses.map(b => ({
      id: b.id,
      name: b.name,
      description: b.description,
      category: b.category,
      services: b.services,
      isOccupied: b.isOccupied
    }));

    const categories = [...new Set(businesses.map(b => b.category).filter(c => c !== 'AVAILABLE'))];

    const prompt = `
      You are an intelligent search engine for the Business Developers District.
      Data: ${JSON.stringify(simplifiedData)}
      Available Categories: ${JSON.stringify(categories)}
      User Query: "${query}"
      Task: Analyze the user's query and return matching IDs with a score (0-100) and filters.
      Sort results by relevance (best matches first).
      Return JSON Object only: {"results": [{"id": "...", "score": 95}], "filters": {"status": "...", "categories": []}}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    const text = response.text || "{}";
    const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const result = JSON.parse(cleanText);

    return {
      results: result.results || [],
      filters: {
        status: result.filters?.status || 'all',
        categories: result.filters?.categories || []
      }
    };
  } catch (error) {
    console.error("AI Search Error:", error);
    return { results: [], filters: { status: 'all', categories: [] } };
  }
};

