declare const ResizeObserver: any;

// --- Constants for Spatial Layout ---
const CONTAINER_SIZE = 1200;
const GRID_COLS = 3;
const PADDING = 120;
const GAP = 120;
const CELL_SIZE = (CONTAINER_SIZE - (PADDING * 2) - (GAP * (GRID_COLS - 1))) / GRID_COLS;
const GLOBE_RADIUS = 320; 

const getCellCenter = (gridPos: {x: number, y: number}) => {
    const colIndex = gridPos.x - 1;
    const rowIndex = gridPos.y - 1;
    const x = PADDING + (colIndex * CELL_SIZE) + (colIndex * GAP) + (CELL_SIZE / 2);
    const y = PADDING + (rowIndex * CELL_SIZE) + (rowIndex * GAP) + (CELL_SIZE / 2);
    return { x, y };
};

type MapMode = 'standard' | 'heatmap' | 'networking' | 'traffic' | 'globe';
type StatusFilter = 'all' | 'occupied' | 'available';
type SortOrder = 'relevance' | 'score';

interface OfficeMapProps {
  businesses: Business[];
  favorites: string[];
  onToggleFavorite: (id: string) => void;
  onRentClick: (business: Business) => void;
  onAddBusiness: (business: Business) => void;
  onUpdateBusiness: (business: Business) => void;
}

// --- Heatmap Floor Layer ---
const HeatmapLayer: React.FC<{ businesses: Business[], intensityMap: Record<string, number> }> = ({ businesses, intensityMap }) => {
    const occupied = businesses.filter(b => b.isOccupied);
    return (
        <svg className="absolute inset-0 w-full h-full pointer-events-none preserve-3d" style={{ transform: 'translateZ(1px)' }}>
            <defs>
                <filter id="heatmap-blur" x="-50%" y="-50%" width="200%" height="200%">
                    <feGaussianBlur in="SourceGraphic" stdDeviation="35" />
                </filter>
            </defs>
            <g filter="url(#heatmap-blur)" opacity="0.7">
                {occupied.map(b => {
                    const center = getCellCenter(b.gridPosition);
                    const intensity = intensityMap[b.id] || 0;
                    const hue = Math.max(0, 240 - (intensity * 240));
                    return (
                        <circle 
                            key={`heat-blob-${b.id}`}
                            cx={center.x} 
                            cy={center.y} 
                            r={CELL_SIZE * (0.6 + intensity * 0.4)} 
                            fill={`hsl(${hue}, 90%, 50%)`}
                            style={{ transition: 'all 2s ease-in-out' }}
                        />
                    );
                })}
            </g>
        </svg>
    );
};

interface BuildingBlockProps {
  business: Business;
  isHovered: boolean;
  isSelected: boolean;
  isFeatured: boolean;
  isSearchMatch?: boolean;
  isFavorite?: boolean;
  lod: 'high' | 'medium' | 'low';
  onSelect: (business: Business) => void;
  onHover: (id: string | null) => void;
  onToggleFavorite: (id: string) => void;
  t: (key: string) => string;
  mapMode: MapMode;
  intensity: number; // New intensity prop
  isNetworkRelated?: boolean;
  networkType?: 'synergy' | 'industry';
  isDimmed?: boolean;
}

const BuildingBlock = React.memo(({ 
  business, isHovered, isSelected, isFeatured, isSearchMatch, isFavorite, lod, 
  onSelect, onHover, onToggleFavorite, t, mapMode, intensity, isNetworkRelated, networkType, isDimmed 
}: BuildingBlockProps) => {
  const isLowLod = lod === 'low';
  const isHighLod = lod === 'high';
  const isDarkMode = mapMode === 'heatmap' || mapMode === 'globe' || mapMode === 'networking';

  const baseDepth = 40;
  const hoverLift = isHovered ? (isLowLod ? 0 : 30) : 0; 
  const selectionLift = isSelected ? 40 : 0;

  let statusColor = 'bg-slate-100'; 
  let dotColor = 'bg-slate-400'; 
  let statusText = t('available');

  const heatmapIntensity = mapMode === 'heatmap' ? intensity : 0;
  const heatmapHue = Math.max(0, 240 - (heatmapIntensity * 240));
  const heatmapSat = 70 + (heatmapIntensity * 30); 
  const heatmapLight = 60 - (heatmapIntensity * 20); 
  const heatmapColorString = `hsl(${heatmapHue}, ${heatmapSat}%, ${heatmapLight}%)`;

  const showPulse = !isLowLod && (
    (mapMode === 'heatmap' && heatmapIntensity > 0.7) || 
    (mapMode === 'traffic' && (business.activeVisitors || 0) > 40) ||
    (mapMode === 'networking' && isNetworkRelated) ||
    isSearchMatch ||
    isFavorite ||
    isSelected
  );
  const pulseClass = showPulse ? 'animate-pulse-slow' : '';

  if (business.isOccupied) {
      if (isSelected) {
          statusColor = 'bg-brand-accent shadow-[0_0_25px_#F7C600] ring-2 ring-white';
          dotColor = 'bg-white';
          statusText = business.name;
      } else if (isSearchMatch) {
          statusColor = 'bg-brand-primary shadow-glow ring-2 ring-white ring-offset-2 ring-offset-brand-primary';
          dotColor = 'bg-white';
          statusText = "Search Match";
      } else if (mapMode === 'heatmap') {
         statusColor = 'shadow-glow text-white'; 
         dotColor = 'bg-white';
         statusText = `${business.activeVisitors} ${t('visitorNow')}`;
      } else if (mapMode === 'traffic') {
         const visitors = business.activeVisitors || 0;
         if (visitors > 40) {
             statusColor = 'bg-rose-600 shadow-glow';
             dotColor = 'bg-rose-200';
         } else if (visitors > 20) {
             statusColor = 'bg-amber-500';
             dotColor = 'bg-amber-200';
         } else {
             statusColor = 'bg-emerald-500';
             dotColor = 'bg-emerald-200';
         }
         statusText = `${visitors} ${t('visitorNow')}`;
      } else if (mapMode === 'networking') {
         if (networkType === 'synergy') {
             statusColor = 'bg-brand-accent shadow-[0_0_15px_#F7C600]';
             dotColor = 'bg-white';
         } else if (networkType === 'industry') {
             statusColor = 'bg-blue-500 shadow-[0_0_15px_#3b82f6]';
             dotColor = 'bg-white';
         } else {
             statusColor = 'bg-slate-700 opacity-40';
             dotColor = 'bg-slate-500';
         }
         statusText = networkType === 'synergy' ? t('highValueMatch') : t('cat_' + business.category);
      } else {
          statusColor = 'bg-brand-primary'; 
          dotColor = 'bg-emerald-400';
          statusText = business.name;
          if (isFeatured) dotColor = 'bg-brand-gold';
      }
  }

  const borderColor = isSelected 
    ? 'border-brand-accent ring-4 ring-brand-accent ring-opacity-60' 
    : isHovered || isSearchMatch || (isFavorite && mapMode === 'standard')
      ? 'border-brand-primary shadow-2xl'
      : (isDarkMode ? 'border-white/10' : 'border-white/20');

  const showContent = isHighLod || isHovered || (mapMode === 'networking' && isNetworkRelated) || isSearchMatch || isFavorite || isSelected;
  const showBanner = (showContent || isSelected) && business.isOccupied && mapMode !== 'globe'; 

  const faceClass = `absolute inset-0 backface-hidden ${!isLowLod ? 'transition-all duration-300' : ''}`;

  const { frontFacade, sideFacade, roofStyle } = useMemo(() => {
    const isOcc = business.isOccupied;
    let wallBase = isOcc ? '#1E293B' : '#F1F5F9';
    let wallGradient = '';

    if (isOcc) {
        if (isSelected) wallBase = '#1E293B';
        else if (isSearchMatch) wallBase = '#2D89E5';
        else if (isFavorite && mapMode === 'standard') wallBase = '#0F172A';
        else if (mapMode === 'heatmap') {
             wallBase = heatmapColorString;
             if (!isLowLod) {
                wallGradient = `linear-gradient(to bottom, 
                    hsl(${heatmapHue}, ${heatmapSat}%, ${Math.min(100, heatmapLight + 15)}%) 0%, 
                    hsl(${heatmapHue}, ${heatmapSat}%, ${Math.max(0, heatmapLight - 15)}%) 100%)`;
             }
        } else if (mapMode === 'traffic') {
             const visitors = business.activeVisitors || 0;
             if (visitors > 40) wallBase = '#e11d48'; 
             else if (visitors > 20) wallBase = '#f59e0b';
             else wallBase = '#10b981';
        } else if (mapMode === 'networking') {
             if (networkType === 'synergy') wallBase = '#F7C600';
             else if (networkType === 'industry') wallBase = '#3b82f6';
             else wallBase = '#0f172a';
        } else if (mapMode === 'globe') {
             wallBase = isOcc ? '#3b82f6' : '#1e293b'; 
        }
    } else if (mapMode === 'globe') {
        wallBase = 'rgba(255,255,255,0.1)';
    }

    if (isLowLod) {
        return {
            frontFacade: { backgroundColor: wallBase },
            sideFacade: { backgroundColor: wallBase, filter: 'brightness(0.7)' },
            roofStyle: { 
                backgroundColor: isOcc ? (mapMode === 'standard' ? (isFavorite ? '#1e293b' : '#0F172A') : wallBase) : (mapMode === 'globe' ? '#334155' : '#FFFFFF'),
                border: isOcc ? 'none' : '1px solid #e2e8f0', 
            }
        };
    }

    const transitionStyle = 'all 0.5s cubic-bezier(0.4, 0, 0.2, 1)';

    const winLight = 'rgba(255,255,255,0.95)';
    const winDim = 'rgba(255,255,255,0.2)';
    const activeWin = isOcc ? (mapMode !== 'standard' ? winDim : winLight) : winDim;

    const windowPattern = `
      linear-gradient(to bottom, transparent 5%, ${activeWin} 5%, ${activeWin} 20%, transparent 20%, transparent 40%, ${activeWin} 40%, ${activeWin} 55%, transparent 55%),
      linear-gradient(to right, transparent 10%, rgba(0,0,0,0.2) 10%, rgba(0,0,0,0.2) 15%, transparent 15%, transparent 85%, rgba(0,0,0,0.2) 85%, rgba(0,0,0,0.2) 90%, transparent 90%)
    `;

    const finalBgImage = (mapMode === 'heatmap' && wallGradient) ? `${windowPattern}, ${wallGradient}` : windowPattern;
    const finalBgSize = '100% 40px';

    const glowColor = isSelected ? '#F7C600' : (mapMode === 'networking' ? wallBase : (mapMode === 'heatmap' ? heatmapColorString : '#3b82f6'));
    const glowStyle = (isOcc || isSelected) ? `0 0 30px ${glowColor}99` : 'none';

    const front = { backgroundColor: wallBase, backgroundImage: finalBgImage, backgroundSize: finalBgSize, boxShadow: `inset 0 0 30px rgba(0,0,0,0.5), ${glowStyle}`, transition: transitionStyle };
    const side = { backgroundColor: wallBase, backgroundImage: finalBgImage, backgroundSize: finalBgSize, filter: 'brightness(0.75)', boxShadow: `inset 0 0 30px rgba(0,0,0,0.6), ${glowStyle}`, transition: transitionStyle };
    const roof = {
        backgroundColor: isOcc ? (mapMode !== 'standard' && mapMode !== 'globe' ? wallBase : '#0F172A') : (mapMode === 'globe' ? '#334155' : '#FFFFFF'),
        backgroundImage: isOcc ? 'radial-gradient(circle at center, rgba(255,255,255,0.1) 0%, transparent 60%)' : 'none',
        transition: transitionStyle,
        border: isSelected ? '3px solid #F7C600' : '1px solid rgba(255,255,255,0.1)'
    };

    return { frontFacade: front, sideFacade: side, roofStyle: roof };
  }, [business.isOccupied, lod, isLowLod, isHighLod, mapMode, isSearchMatch, isFavorite, isSelected, heatmapIntensity, networkType, heatmapColorString, heatmapHue, heatmapSat, heatmapLight]);

  const roofClasses = isLowLod
    ? `absolute inset-0 border-2 ${borderColor} overflow-hidden flex flex-col items-center justify-center p-2 text-center backface-hidden z-20`
    : `absolute inset-0 border-2 ${borderColor} rounded-sm overflow-hidden flex flex-col items-center justify-center p-2 text-center shadow-inner backface-hidden z-20 transition-colors duration-300`;

  return (
    <div
      onClick={(e) => { e.stopPropagation(); onSelect(business); }}
      onMouseEnter={() => onHover(business.id)}
      onMouseLeave={() => onHover(null)}
      className={`relative w-full h-full group pointer-events-auto cursor-pointer preserve-3d transition-all duration-500 ${pulseClass} ${isDimmed ? 'opacity-30 grayscale' : 'opacity-100'}`}
    >
        {!isLowLod && mapMode !== 'globe' && (
            <div 
              className={`absolute inset-0 rounded-full transition-all duration-500 ${isHighLod ? 'blur-xl' : 'blur-md'} ${isSelected ? 'bg-brand-accent/40 scale-150 animate-pulse' : 'bg-black/30'}`}
              style={{ transform: `translateZ(0) scale(${isHovered || isSearchMatch || isSelected ? 0.9 : 0.8})`, opacity: isHovered || isSearchMatch || isSelected ? 0.5 : 0.3 }}
            />
        )}

        <div 
          className={`w-full h-full preserve-3d ${!isLowLod ? 'transition-transform duration-500 cubic-bezier(0.4, 0, 0.2, 1)' : 'transition-none'} will-change-transform`}
          style={{ transform: `translateZ(${baseDepth + hoverLift + selectionLift}px)` }}
        >
            {business.isOccupied ? (
                <>
                  <div className={roofClasses} style={roofStyle}>
                      {/* Favorite Toggle */}
                      <button 
                        onClick={(e) => { e.stopPropagation(); onToggleFavorite(business.id); }}
                        className={`absolute top-2 left-2 z-40 p-1.5 rounded-lg transition-all duration-300 ${isFavorite ? 'bg-rose-500 text-white shadow-glow-sm scale-110' : 'bg-white/10 text-white/40 hover:bg-white/20 hover:text-white'}`}
                      >
                         <svg className={`w-3.5 h-3.5 ${isFavorite ? 'fill-current' : 'fill-none'}`} viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                            <path strokeLinecap="round" strokeLinejoin="round" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                         </svg>
                      </button>

                      {!isLowLod && (
                        <div className={`absolute top-2 right-2 w-2.5 h-2.5 rounded-full ${dotColor} ${showPulse ? 'animate-ping' : ''} z-30`} />
                      )}
                      {showContent && (
                        <div className="animate-fade-in flex flex-col items-center relative z-10">
                          <div className={`w-14 h-14 rounded-lg bg-white p-0.5 border shadow-lg relative mb-2 transition-all ${isSelected ? 'border-brand-accent scale-125' : isSearchMatch ? 'border-brand-primary scale-110' : 'border-slate-700/50'}`}>
                              {business.logoUrl ? (
                                  <img src={business.logoUrl} alt="" className="w-full h-full object-cover rounded" />
                              ) : (
                                  <div className="w-full h-full bg-slate-900 flex items-center justify-center text-[8px] text-white font-bold">BIZ</div>
                              )}
                          </div>
                          {(isHighLod || isHovered || isNetworkRelated || isSearchMatch || isFavorite || isSelected) && (
                             <h3 className={`font-sans font-bold text-white text-[11px] truncate w-full px-1 tracking-wide uppercase bg-black/40 rounded px-1 backdrop-blur-sm ${isSelected ? 'text-brand-accent border border-brand-accent/30' : ''}`}>{business.name}</h3>
                          )}
                        </div>
                      )}
                  </div>
                  <div className={`${faceClass} origin-bottom rotate-x-90 h-[40px] bottom-0 border-b border-white/5`} style={frontFacade}></div>
                  <div className={`${faceClass} origin-top rotate-x-[-90deg] h-[40px] top-0 brightness-75`} style={frontFacade} />
                  <div className={`${faceClass} origin-right rotate-y-90 w-[40px] right-0 top-0 bottom-0`} style={sideFacade} />
                  <div className={`${faceClass} origin-left rotate-y-[-90deg] w-[40px] left-0 top-0 bottom-0`} style={sideFacade} />
                </>
            ) : (
                <div className={`w-full h-full relative preserve-3d ${!isLowLod ? 'opacity-80 hover:opacity-100 transition-all duration-300 group-hover:scale-105' : 'opacity-60'}`}>
                  <div className={`absolute inset-0 border-2 ${isLowLod ? (isDarkMode ? 'border-white/10' : 'border-slate-200') : (isDarkMode ? 'border-white/20' : 'border-slate-300')} ${isDarkMode ? 'bg-slate-800/50' : 'bg-white/60'} ${!isLowLod ? 'backdrop-blur-sm rounded-sm' : ''} flex flex-col items-center justify-center ${borderColor}`}>
                      {isHovered && (
                          <div className="bg-brand-accent text-white text-[10px] font-bold px-3 py-1 rounded-full shadow-lg uppercase tracking-wide">
                              {t('available')}
                          </div>
                      )}
                      {!isLowLod && !isHovered && <span className={`text-3xl ${isDarkMode ? 'text-white/20' : 'text-slate-300'}`}>+</span>}
                  </div>
                </div>
            )}

            {/* Selection Beacon */}
            {isSelected && !isLowLod && (
                <div className="absolute top-1/2 left-1/2 w-0 h-0 preserve-3d pointer-events-none z-[60]" style={{ transform: 'translateZ(120px)' }}>
                   <div className="absolute top-0 left-0 -translate-x-1/2 -translate-y-full flex flex-col items-center animate-beacon">
                        <div className="w-10 h-10 bg-brand-accent rounded-full border-4 border-white shadow-[0_0_25px_#F7C600] flex items-center justify-center">
                            <svg className="w-6 h-6 text-brand-dark" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5.05 4.05a7 7 0 119.9 9.9L10 18.9l-4.95-4.95a7 7 0 010-9.9zM10 11a2 2 0 100-4 2 2 0 000 4z" clipRule="evenodd" /></svg>
                        </div>
                        <div className="w-2 h-14 bg-gradient-to-t from-brand-accent/0 via-brand-accent/60 to-brand-accent shadow-[0_0_15px_#F7C600]"></div>
                   </div>
                </div>
            )}

            {showBanner && business.isOccupied && (
              <div className="absolute top-1/2 left-1/2 w-0 h-0 preserve-3d pointer-events-none z-50" style={{ transform: 'translateZ(100px)' }} >
                 <div className="absolute top-0 left-0 flex flex-col items-center gap-1 transition-all duration-300 origin-bottom" style={{ transform: `translate(-50%, -100%) rotateX(var(--map-inv-rotate-x)) rotateZ(var(--map-inv-rotate-z))` }} >
                    <div className={`px-4 py-2 rounded-xl shadow-2xl border border-white/20 flex flex-col items-center gap-0.5 ${statusColor} backdrop-blur-md min-w-[120px]`} style={mapMode === 'heatmap' ? { backgroundColor: heatmapColorString } : {}}>
                      <span className={`text-[11px] font-bold uppercase tracking-widest ${isSelected ? 'text-brand-dark' : 'text-white'}`}>{business.name}</span>
                      <span className={`text-[8px] font-bold opacity-80 uppercase tracking-tighter ${isSelected ? 'text-brand-dark/60' : 'text-white/60'}`}>{t('cat_' + business.category)}</span>
                    </div>
                    <div className={`w-0.5 h-8 opacity-80 ${statusColor}`} style={mapMode === 'heatmap' ? { backgroundColor: heatmapColorString } : {}}></div>
                 </div>
              </div>
            )}
        </div>
        <style>{`
          @keyframes beacon-float {
            0%, 100% { transform: translate(-50%, -100%) translateY(0); }
            50% { transform: translate(-50%, -100%) translateY(-30px); }
          }
          .animate-beacon { animation: beacon-float 1.8s infinite cubic-bezier(0.4, 0, 0.2, 1); }
        `}</style>
    </div>
  );
});

interface NetworkingLayerProps {
    connections: any[];
    activeId: string | null;
}

const NetworkingLayer: React.FC<NetworkingLayerProps> = ({ connections, activeId }) => {
    return (
        <svg className="absolute inset-0 w-full h-full pointer-events-none preserve-3d" style={{ transform: 'translateZ(2px)' }}>
            <defs>
                <filter id="net-glow" x="-20%" y="-20%" width="140%" height="140%">
                    <feGaussianBlur stdDeviation="4" result="blur" />
                    <feComposite in="SourceGraphic" in2="blur" operator="over" />
                </filter>
            </defs>
            {connections.map(conn => {
                const isRelevant = !activeId || conn.participants.includes(activeId);
                const opacity = isRelevant ? 0.9 : 0.1;
                const color = conn.type === 'synergy' ? '#F7C600' : '#3b82f6';
                const strokeWidth = conn.type === 'synergy' ? 3 : 1.5;

                return (
                    <g key={conn.id} className="transition-opacity duration-500" style={{ opacity }}>
                        <line 
                            x1={conn.start.x} y1={conn.start.y} 
                            x2={conn.end.x} y2={conn.end.y} 
                            stroke={color} 
                            strokeWidth={strokeWidth} 
                            strokeDasharray={conn.type === 'synergy' ? "10, 5" : "none"}
                            filter="url(#net-glow)"
                            className={conn.type === 'synergy' ? 'animate-dash-flow' : ''}
                        />
                        {isRelevant && (
                            <circle r={strokeWidth * 1.5} fill="#fff">
                                <animateMotion 
                                    dur={conn.type === 'synergy' ? '3s' : '6s'} 
                                    repeatCount="indefinite" 
                                    path={`M${conn.start.x},${conn.start.y} L${conn.end.x},${conn.end.y}`} 
                                />
                            </circle>
                        )}
                    </g>
                );
            })}
        </svg>
    );
};

const OfficeMap: React.FC<OfficeMapProps> = ({ businesses, favorites, onToggleFavorite, onRentClick, onAddBusiness, onUpdateBusiness }) => {
  const { t, language } = useLanguage();
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [selectedBusinessId, setSelectedBusinessId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [mapMode, setMapMode] = useState<MapMode>('standard');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [sortOrder, setSortOrder] = useState<SortOrder>('relevance');

  const [isSearchingAI, setIsSearchingAI] = useState(false);
  const [aiSearchResults, setAiSearchResults] = useState<AISearchResult[] | null>(null);
  const [showOnlyFavorites, setShowOnlyFavorites] = useState(false);

  const [showInsights, setShowInsights] = useState(false);
  const [insightsContent, setInsightsContent] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Momentum / Rate of Change State
  const prevVisitorsRef = useRef<Record<string, number>>({});

  const intensityMap = useMemo(() => {
    const map: Record<string, number> = {};
    businesses.forEach(b => {
      if (!b.isOccupied) return;
      const current = b.activeVisitors || 0;
      const prev = prevVisitorsRef.current[b.id] ?? current;
      const delta = current - prev;

      // Base intensity on absolute volume (normalized to 60 max)
      const baseIntensity = current / 60;

      // Momentum component: if visitors are growing, increase intensity
      const momentumFactor = delta > 0 ? (delta / 15) : (delta < 0 ? (delta / 40) : 0);

      // Final clamped score (70% volume, 30% velocity)
      const combined = (baseIntensity * 0.7) + (momentumFactor * 0.3);
      map[b.id] = Math.max(0, Math.min(1, combined));

      // Update ref for next calculation
      prevVisitorsRef.current[b.id] = current;
    });
    return map;
  }, [businesses]);

  // AI Narrative State - Now structured
  const [businessNarrative, setBusinessNarrative] = useState<DigitalTwinReport | null>(null);
  const [isGeneratingNarrative, setIsGeneratingNarrative] = useState(false);

  const [interactionMode, setInteractionMode] = useState<'pan' | 'rotate'>('pan');
  const [viewState, setViewState] = useState({ zoom: 0.8, rotateX: 55, rotateZ: 45, panX: 0, panY: 0 });
  const [isDragging, setIsDragging] = useState(false);

  const lastMousePos = useRef<{x: number, y: number} | null>(null);
  const lastTouchPos = useRef<{x: number, y: number} | null>(null);
  const lastTouchDist = useRef<number | null>(null);
  const mapContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
      if (mapMode === 'globe') {
          setViewState({ zoom: 0.9, rotateX: 0, rotateZ: 0, panX: 0, panY: 0 });
          setInteractionMode('rotate');
      } else {
          setViewState({ zoom: 0.8, rotateX: 55, rotateZ: 45, panX: 0, panY: 0 });
          setInteractionMode('pan');
      }
  }, [mapMode]);

  // Extract unique categories from businesses for the filter dropdown
  const uniqueCategories = useMemo(() => {
    const cats = businesses.map(b => b.category).filter(c => c !== 'AVAILABLE');
    return Array.from(new Set(cats));
  }, [businesses]);

  const handleAISearch = async () => {
    if (!searchQuery.trim()) return;
    setIsSearchingAI(true);
    try {
      const result = await searchBusinessesWithAI(searchQuery, businesses, language);
      setAiSearchResults(result.results);

      if (result.results.length > 0) {
          const matchingIds = result.results.map(r => r.id);
          const matchingBusinesses = businesses.filter(b => matchingIds.includes(b.id));
          let avgX = 0, avgY = 0;
          matchingBusinesses.forEach(b => {
              const pos = getCellCenter(b.gridPosition);
              avgX += pos.x;
              avgY += pos.y;
          });
          avgX /= matchingBusinesses.length;
          avgY /= matchingBusinesses.length;

          const panX = (CONTAINER_SIZE / 2 - avgX) * viewState.zoom;
          const panY = (CONTAINER_SIZE / 2 - avgY) * viewState.zoom;

          setViewState(prev => ({ 
              ...prev, 
              panX, 
              panY,
              zoom: result.results.length < 3 ? 1.3 : 0.85
          }));
      }
    } catch (e) { 
      console.error(e); 
    } finally { 
      setIsSearchingAI(false); 
    }
  };

  const handleResetFilters = () => {
      setSearchQuery('');
      setAiSearchResults(null);
      setShowOnlyFavorites(false);
      setStatusFilter('all');
      setCategoryFilter('all');
      setSortOrder('relevance');
      setViewState({ zoom: 0.8, rotateX: 55, rotateZ: 45, panX: 0, panY: 0 });
  };

  const handleSelectFromResult = (business: Business) => {
      setSelectedBusinessId(business.id);
      setIsSidebarOpen(true);
      setBusinessNarrative(null);
      const pos = getCellCenter(business.gridPosition);
      setViewState(prev => ({
          ...prev,
          panX: (CONTAINER_SIZE / 2 - pos.x) * prev.zoom,
          panY: (CONTAINER_SIZE / 2 - pos.y) * prev.zoom,
          zoom: 1.4
      }));
  };

  const networkingConnections = useMemo(() => {
    if (mapMode !== 'networking') return [];
    const connections: any[] = [];
    const occupied = businesses.filter(b => b.isOccupied);
    for (let i = 0; i < occupied.length; i++) {
        for (let j = i + 1; j < occupied.length; j++) {
            const b1 = occupied[i];
            const b2 = occupied[j];
            const hasSynergy = b1.genomeProfile?.servicesNeeded?.some(need => 
                b2.genomeProfile?.servicesOffered?.some(offer => offer.toLowerCase().includes(need.toLowerCase()) || need.toLowerCase().includes(offer.toLowerCase()))
            ) || b2.genomeProfile?.servicesNeeded?.some(need => 
                b1.genomeProfile?.servicesOffered?.some(offer => offer.toLowerCase().includes(need.toLowerCase()) || need.toLowerCase().includes(offer.toLowerCase()))
            );
            let type: 'synergy' | 'industry' | null = null;
            if (hasSynergy) type = 'synergy';
            else if (b1.category === b2.category) type = 'industry';
            if (type) {
                connections.push({ id: `${b1.id}-${b2.id}`, participants: [b1.id, b2.id], start: getCellCenter(b1.gridPosition), end: getCellCenter(b2.gridPosition), type });
            }
        }
    }
    return connections;
  }, [businesses, mapMode]);

  const trafficSegments = useMemo(() => {
    if (mapMode !== 'traffic') return [];
    const segments = [];
    for (let c = 1; c < GRID_COLS; c++) {
        const x = PADDING + (c-1)*(CELL_SIZE+GAP) + CELL_SIZE + GAP/2;
        const nearby = businesses.filter(b => b.isOccupied && (b.gridPosition.x === c || b.gridPosition.x === c + 1));
        const visitors = nearby.reduce((acc, b) => acc + (b.activeVisitors || 0), 0);
        segments.push({ id: `v-${c}`, x1: x, y1: PADDING, x2: x, y2: CONTAINER_SIZE - PADDING, visitors: visitors, orientation: 'vertical' });
    }
    for (let r = 1; r < GRID_COLS; r++) { 
         const y = PADDING + (r-1)*(CELL_SIZE+GAP) + CELL_SIZE + GAP/2;
         const nearby = businesses.filter(b => b.isOccupied && (b.gridPosition.y === r || b.gridPosition.y === r + 1));
         const visitors = nearby.reduce((acc, b) => acc + (b.activeVisitors || 0), 0);
         segments.push({ id: `h-${r}`, x1: PADDING, y1: y, x2: CONTAINER_SIZE - PADDING, y2: y, visitors: visitors, orientation: 'horizontal' });
    }
    return segments;
  }, [businesses, mapMode]);

  const handleAnalyzeTrends = async () => {
      setIsAnalyzing(true);
      setShowInsights(true);
      try {
          const result = await analyzeMapTrends(businesses, language);
          setInsightsContent(result);
      } catch (e) { console.error(e); setInsightsContent("Failed to generate insights."); } finally { setIsAnalyzing(false); }
  };

  const handleGenerateNarrative = async (biz: Business) => {
      setIsGeneratingNarrative(true);
      try {
          // Add some mocked dynamic context based on neighbors
          const neighbors = businesses.filter(b => b.isOccupied && b.id !== biz.id && Math.abs(b.gridPosition.x - biz.gridPosition.x) <= 1 && Math.abs(b.gridPosition.y - biz.gridPosition.y) <= 1);
          const context = neighbors.length > 0 ? `Nearby companies like ${neighbors[0].name} are active in ${neighbors[0].category}.` : "In a developing sector of the district.";

          const narrative = await generateBusinessNarrative(biz, context, language);
          setBusinessNarrative(narrative);
      } catch (e) {
          console.error(e);
      } finally {
          setIsGeneratingNarrative(false);
      }
  };

  const handleMouseDown = (e: React.MouseEvent) => { 
      if ((e.target as HTMLElement).closest('button') || (e.target as HTMLElement).closest('input') || (e.target as HTMLElement).closest('select') || (e.target as HTMLElement).closest('.search-result-item')) return;
      setIsDragging(true); lastMousePos.current = { x: e.clientX, y: e.clientY }; 
  };

  const handleMouseMove = (e: React.MouseEvent) => {
      if (!isDragging || !lastMousePos.current) return;
      const dx = e.clientX - lastMousePos.current.x;
      const dy = e.clientY - lastMousePos.current.y;
      updateNavigation(dx, dy);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
  };

  const updateNavigation = (dx: number, dy: number) => {
      if (mapMode === 'globe') {
          setViewState(prev => ({ ...prev, rotateZ: prev.rotateZ + dx * 0.5, rotateX: prev.rotateX - dy * 0.5 }));
      } else if (interactionMode === 'rotate') {
         setViewState(prev => ({ ...prev, rotateZ: prev.rotateZ + dx * 0.3, rotateX: Math.max(0, Math.min(85, prev.rotateX - dy * 0.3)) }));
      } else {
         setViewState(prev => ({ ...prev, panX: prev.panX + dx, panY: prev.panY + dy }));
      }
  };

  const handleMouseUp = () => setIsDragging(false);

  const handleWheel = (e: React.WheelEvent) => {
      const zoomSpeed = 0.0015;
      const delta = -e.deltaY;
      setViewState(prev => ({
          ...prev,
          zoom: Math.max(0.4, Math.min(2.5, prev.zoom + delta * zoomSpeed))
      }));
  };

  const handleTouchStart = (e: React.TouchEvent) => {
      if ((e.target as HTMLElement).closest('button') || (e.target as HTMLElement).closest('input') || (e.target as HTMLElement).closest('select')) return;
      setIsDragging(true);
      if (e.touches.length === 1) {
          lastTouchPos.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
          lastTouchDist.current = null;
      } else if (e.touches.length === 2) {
          const dist = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY);
          lastTouchDist.current = dist;
      }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      if (!isDragging) return;
      if (e.touches.length === 1 && lastTouchPos.current) {
          const dx = e.touches[0].clientX - lastTouchPos.current.x;
          const dy = e.touches[0].clientY - lastTouchPos.current.y;
          updateNavigation(dx, dy);
          lastTouchPos.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
      } else if (e.touches.length === 2 && lastTouchDist.current) {
          const dist = Math.hypot(e.touches[0].clientX - e.touches[1].clientX, e.touches[0].clientY - e.touches[1].clientY);
          const delta = dist - lastTouchDist.current;
          const zoomSpeed = 0.005;
          setViewState(prev => ({
              ...prev,
              zoom: Math.max(0.4, Math.min(2.5, prev.zoom + delta * zoomSpeed))
          }));
          lastTouchDist.current = dist;
      }
  };

  const handleTouchEnd = () => {
      setIsDragging(false);
      lastTouchPos.current = null;
      lastTouchDist.current = null;
  };

  const selectedBusiness = useMemo(() => businesses.find(b => b.id === selectedBusinessId) || null, [businesses, selectedBusinessId]);

  // Automatically trigger dynamic description when business is selected
  useEffect(() => {
    if (selectedBusiness && selectedBusiness.isOccupied) {
      handleGenerateNarrative(selectedBusiness);
    }
  }, [selectedBusinessId]);

  let currentLod: 'low' | 'medium' | 'high' = 'medium';
  if (viewState.zoom < 0.65 || mapMode === 'globe') currentLod = 'low';
  else if (viewState.zoom > 1.25) currentLod = 'high';

  const getNetworkStatus = (id: string) => {
    if (mapMode !== 'networking') return { isRelated: false };
    const activeId = hoveredId || selectedBusinessId;
    if (!activeId) return { isRelated: true };
    if (id === activeId) return { isRelated: true };
    const conn = networkingConnections.find(c => c.participants.includes(id) && c.participants.includes(activeId));
    if (conn) return { isRelated: true, type: conn.type };
    return { isRelated: false };
  };

  const sidebarResults = useMemo(() => {
    const aiIds = aiSearchResults?.map(r => r.id) || [];
    let filtered = businesses.filter(b => (aiIds.includes(b.id) || (showOnlyFavorites && favorites.includes(b.id))));

    filtered = filtered.filter(business => {
        const isFilteredOutByStandardFilters = 
           (statusFilter === 'occupied' && !business.isOccupied) ||
           (statusFilter === 'available' && business.isOccupied) ||
           (categoryFilter !== 'all' && business.category !== categoryFilter);
        return !isFilteredOutByStandardFilters;
    });

    if (aiSearchResults) {
        if (sortOrder === 'score') {
            filtered.sort((a, b) => {
                const scoreA = aiSearchResults.find(r => r.id === a.id)?.score || 0;
                const scoreB = aiSearchResults.find(r => r.id === b.id)?.score || 0;
                return scoreB - scoreA;
            });
        } else {
            filtered.sort((a, b) => {
                const idxA = aiSearchResults.findIndex(r => r.id === a.id);
                const idxB = aiSearchResults.findIndex(r => r.id === b.id);
                return idxA - idxB;
            });
        }
    }

    return filtered;
  }, [businesses, aiSearchResults, favorites, showOnlyFavorites, statusFilter, categoryFilter, sortOrder]);

  const aiMatchingIds = useMemo(() => aiSearchResults?.map(r => r.id) || [], [aiSearchResults]);

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 w-full relative">
       <div 
          className={`relative flex-1 h-[600px] lg:h-full overflow-hidden rounded-[32px] border shadow-inner group outline-none transition-colors duration-700 select-none ${
              mapMode === 'globe' ? 'bg-slate-900 border-slate-700' : 
              mapMode === 'heatmap' ? 'bg-[#05070a] border-white' : 
              mapMode === 'networking' ? 'bg-[#0B1121] border-brand-primary/20' : 'bg-[#F1F5F9] border-white'
          }`}
          style={{ touchAction: 'none' }}
          ref={mapContainerRef}
          onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}
          onWheel={handleWheel}
          onTouchStart={handleTouchStart} onTouchMove={handleTouchMove} onTouchEnd={handleTouchEnd}
       >
           {/* Scene Enhancements */}
           {(mapMode === 'globe' || mapMode === 'networking' || mapMode === 'heatmap') && (
