           <div className="absolute top-6 left-6 z-20 flex flex-col gap-4 pointer-events-none">
               <div className="pointer-events-auto bg-white/90 backdrop-blur-xl shadow-card border border-white/50 rounded-2xl p-5 w-80 max-h-[85vh] flex flex-col">
                   <h2 className="text-xl font-bold text-brand-primary mb-4 font-heading">{t('businessMap')}</h2>

                   {/* Search & Filter Area */}
                   <div className="relative mb-4 space-y-3 shrink-0">
                       <div className="relative">
                           <input 
                              type="text" 
                              value={searchQuery} 
                              onChange={(e) => setSearchQuery(e.target.value)} 
                              onKeyDown={(e) => e.key === 'Enter' && handleAISearch()}
                              placeholder={t('aiSearchPlaceholder')} 
                              className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-sm outline-none focus:ring-2 focus:ring-brand-accent/20 focus:border-brand-accent transition-all font-medium text-brand-primary" 
                           />
                           <div className="absolute right-2 top-2 flex gap-1">
                                {(searchQuery || aiSearchResults || showOnlyFavorites) && (
                                    <button 
                                        onClick={handleResetFilters}
                                        className="p-1.5 text-slate-300 hover:text-slate-500 transition-colors"
                                    >
                                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                                    </button>
                                )}
                                <button 
                                    onClick={handleAISearch} 
                                    disabled={isSearchingAI || !searchQuery.trim()}
                                    className="p-1.5 bg-brand-primary text-white rounded-lg hover:brightness-110 disabled:opacity-50 transition-all shadow-sm"
                                >
                                    {isSearchingAI ? (
                                        <div className="w-4 h-4 border-2 border-white/30 border-t-transparent rounded-full animate-spin"></div>
                                    ) : (
                                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                                    )}
                                </button>
                           </div>
                       </div>

                       <div className="grid grid-cols-2 gap-2">
