               <div className="p-6 bg-brand-dark border-b border-white/5 flex justify-between items-start text-white">
                   <div className="min-w-0 flex-1">
                       <div className="flex items-center gap-3 mb-1">
                           <h2 className="text-xl font-bold font-heading truncate">{selectedBusiness.name}</h2>
                           {favorites.includes(selectedBusiness.id) && <span className="text-rose-500 text-lg">❤️</span>}
                       </div>
                       <div className="flex items-center gap-2">
                          <span className="text-[10px] font-bold uppercase tracking-widest text-brand-primary">{t('cat_' + selectedBusiness.category)}</span>
                          <span className="w-1 h-1 rounded-full bg-white/20"></span>
                          <span className="text-[10px] font-mono text-slate-400">UUID: {selectedBusiness.id.padStart(8, '0')}</span>
                       </div>
                   </div>
                   <button onClick={() => setIsSidebarOpen(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors text-slate-400">✕</button>
               </div>

               <div className="flex-1 overflow-y-auto custom-scrollbar flex flex-col bg-slate-50/50">
                   {/* Logo Visuals */}
                   <div className="p-6 border-b border-slate-100 bg-white">
                       <div className="w-full h-44 bg-slate-50 rounded-2xl border border-slate-200 flex items-center justify-center overflow-hidden relative shadow-inner group">
                          {selectedBusiness.logoUrl ? (
                              <img src={selectedBusiness.logoUrl} className="w-full h-full object-cover opacity-90 group-hover:scale-105 transition-transform duration-700 grayscale hover:grayscale-0" alt="logo" />
                          ) : (
                              <div className="text-4xl font-bold text-slate-100 font-mono">DISTRICT_ASSET</div>
