                          {selectedBusiness.isOccupied && (
                              <div className="absolute top-4 right-4 bg-brand-dark/90 backdrop-blur-md px-3 py-1.5 rounded-lg border border-white/10 flex items-center gap-2 shadow-lg">
                                  <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                                  <span className="text-[9px] font-mono font-bold text-white uppercase tracking-widest">{selectedBusiness.activeVisitors} LIVE NODES</span>
                              </div>
